import click
import pytest
from click.testing import CliRunner


@pytest.mark.parametrize(("args", "env", "mapping", "expected"), [(["--name", "cli"], {"CHECK_NAME": "environment"}, {"name": "mapped"}, "cli:COMMANDLINE"), ([], {"CHECK_NAME": "environment"}, {"name": "mapped"}, "environment:ENVIRONMENT"), ([], {}, {"name": "mapped"}, "mapped:DEFAULT_MAP"), ([], {}, {}, "fallback:DEFAULT")])
def test_resolution_impact(args, env, mapping, expected):
    @click.command()
    @click.option("--name", envvar="CHECK_NAME", default="fallback")
    @click.pass_context
    def command(ctx, name):
        click.echo(f"{name}:{ctx.get_parameter_source('name').name}")
    result = CliRunner().invoke(command, args, env=env, default_map=mapping)
    assert result.exit_code == 0
    assert result.output.strip() == expected

import httpx
import pytest


@pytest.mark.parametrize(("arguments", "expected"), [({}, 7.0), ({"timeout": None}, None), ({"timeout": 3.0}, 3.0)])
def test_build_timeout(arguments, expected):
    client = httpx.Client(timeout=7.0, trust_env=False)
    request = client.build_request("GET", "http://example.invalid", **arguments)
    assert request.extensions["timeout"] == dict.fromkeys(("connect", "read", "write", "pool"), expected)


def test_explicit_extension_and_raw_send():
    captured = []
    def handle(request):
        captured.append(request.extensions["timeout"])
        return httpx.Response(200)
    with httpx.Client(timeout=7.0, trust_env=False, transport=httpx.MockTransport(handle)) as client:
        explicit = {"connect": 1, "read": 2, "write": 3, "pool": 4}
        built = client.build_request("GET", "http://example.invalid", timeout=99, extensions={"timeout": explicit})
        client.send(built)
        client.send(httpx.Request("GET", "http://example.invalid"))
    assert captured == [explicit, dict.fromkeys(("connect", "read", "write", "pool"), 7.0)]
